Step 2 — parse the values to numeric percentages and compute the 3-year average (rounded to 1 decimal place):
```python
# Step 2: parse percent values robustly and compute the mean
import re, numpy as np

def parse_percent(row):
    v = row.get('value')
    n = row.get('number')
    # prefer explicit percent in 'value'
    if isinstance(v, str) and '%' in v:
        try:
            return float(v.replace('%','').strip())
        except:
            return np.nan
    # otherwise, if 'number' is present and numeric, use it
    try:
        if n is not None and n != 'NULL' and str(n).strip() != '':
            return float(n)
    except:
        pass
    # fallback: try to parse 'value' as numeric
    try:
        return float(str(v).strip())
    except:
        return np.nan

DF_subset['net_profit_margin_pct'] = DF_subset.apply(parse_percent, axis=1)
avg_margin = round(DF_subset['net_profit_margin_pct'].mean(), 1)
# return the intermediate table and the final computed average
DF_subset, avg_margin
```

