# DF is assumed to be provided as a DataFrame.
keywords = [
    'tax', 'taxes', 'provision', 'effective tax rate', 'effective tax', 'effective rate',
    'income tax', 'income taxes', 'income (loss) before', 'income before', 'benefit', 'income tax benefit',
    'fy2022', 'fy 2022', 'fy2021', 'fy 2021', '2022', '2021', '%'
]

def row_matches_any(row):
    # join all string fields in the row and search
    s = ' '.join([str(x) for x in row.fillna('').values]).lower()
    for kw in keywords:
