Python: ```# Step 2: If matched rows include lines for "Income before income taxes" and "Provision for income taxes",
# extract numeric values for FY2022 and FY2021 and compute effective tax rates.
import re
def extract_number_from_text(s):
    if pd.isna(s):
        return None
    s = str(s)
    # try to find a percent first
    m = re.search(r'(-?\d+[\.,]?\d*)\s*%', s)
    if m:
        return float(m.group(1).replace(',','.'))/100.0, 'percent'
    # try to find a plain number
    m = re.search(r'(-?\d{1,3}(?:,\d{3})*(?:\.\d+)?|\-?\d+(?:\.\d+)?)', s)
    if m:
        return float(m.group(1).replace(',','')), 'number'
    return None, None

# find candidate rows for income_before and provision based on line_item text
income_candidates = matched[matched['line_item'].str.lower().str.contains('income') | matched['line_item'].str.lower().str.contains('loss before') | matched['line_item'].str.lower().str.contains('income (loss) before', na=False)]
provision_candidates = matched[matched['line_item'].str.lower().str.contains('provision') | matched['line_item'].str.lower().str.contains('income tax', na=False) | matched['line_item'].str.lower().str.contains('taxes', na=False)]

# helper to extract values for 2022 and 2021 from a candidate row's period/value/number columns
def get_year_values(df_rows):
    # returns dict: {year: numeric_value}
    results = {}
    for _, r in df_rows.iterrows():
        # search for year token in any column
        row_text = ' '.join([str(x) for x in r[['period','value','line_item','page']].fillna('')]).lower()
        yr = None
        if '2022' in row_text:
            yr = 2022
        elif '2021' in row_text:
            yr = 2021
        # fallback: sometimes period column may be 'FY 2022' or 'FY2022' or just '2022'
        if yr is None:
            m = re.search(r'20(21|22)', row_text)
            if m:
                yr = int('20' + m.group(1))
        # if still unknown, try to parse numeric columns as a time series separated by known column order (less reliable)
        val_candidate = None
        # prefer numeric column 'number' if present
        if 'number' in r and pd.notna(r['number']):
            try:
                val_candidate = float(r['number'])
            except:
                val_candidate = None
        # otherwise try the 'value' text (may contain commas/units)
        if val_candidate is None and pd.notna(r.get('value', None)):
            num, typ = extract_number_from_text(r['value'])
            if typ == 'number':
                val_candidate = num
            elif typ == 'percent':
                val_candidate = num  # as fraction
        if yr is not None and val_candidate is not None:
            results[yr] = val_candidate
    return results

income_vals = get_year_values(income_candidates)
provision_vals = get_year_values(provision_candidates)

# Compute effective tax rates if both pieces found for 2021 and/or 2022
rates = {}
for yr in (2021, 2022):
    if yr in income_vals and yr in provision_vals and income_vals[yr] != 0:
        rates[yr] = provision_vals[yr] / income_vals[yr]
    else:
        rates[yr] = None

# Prepare output DataFrame
out = pd.DataFrame([
    {'year': 2021, 'income_before_taxes': income_vals.get(2021), 'provision_for_taxes': provision_vals.get(2021), 'effective_tax_rate': rates.get(2021)},
    {'year': 2022, 'income_before_taxes': income_vals.get(2022), 'provision_for_taxes': provision_vals.get(2022), 'effective_tax_rate': rates.get(2022)}
])
out
