# Expecting the executor to return the intermediate table from the SQL above as DF.
import pandas as pd
import numpy as np
import re

df = DF.copy()

years = ['2019','2020','2021']
results = []

def choose_value(rows):
    # prefer 'number' column if present and numeric; fallback to 'value' then try to parse.
    if rows.empty:
        return np.nan
    # If multiple candidate rows, try to prefer rows mentioning "total" or exact "net sales"
    rows_lc = rows.copy()
    rows_lc['li_lc'] = rows_lc['line_item'].str.lower().fillna('')
    # preference order
    for kw in ['total net sales', 'total sales', 'net sales', 'net sales (gaap)', 'net sales (non-gaap)', 'revenues', 'revenue', 'sales']:
        sel = rows_lc[rows_lc['li_lc'].str.contains(kw)]
        if not sel.empty:
            rows = sel
            break
    # take the largest numeric 'number' if multiple
    if 'number' in rows.columns:
        try:
            nums = pd.to_numeric(rows['number'], errors='coerce')
            if nums.notna().any():
                return float(nums.fillna(0).max())
        except:
            pass
    # fallback: try parse 'value' column
    if 'value' in rows.columns:
        try:
            vals = pd.to_numeric(rows['value'].astype(str).str.replace(',',''), errors='coerce')
            if vals.notna().any():
                return float(vals.fillna(0).max())
        except:
            pass
    # last resort: try to parse any numeric in line_item or value text
    for col in ['value','number','line_item']:
        if col in rows.columns:
            for v in rows[col].astype(str):
                m = re.search(r'(-?\d[\d,\.]*)', v)
                if m:
                    try:
                        return float(m.group(1).replace(',',''))
                    except:
                        continue
    return np.nan

for y in years:
    sub = df[df['period']==y]
    op_rows = sub[sub['line_item'].str.lower().str.contains('operat', na=False)]
    # also accept 'income from operations' synonyms
    if op_rows.empty:
        op_rows = sub[sub['line_item'].str.lower().str.contains('income from operations|income \\(loss\\) from operations', na=False)]
    op_val = choose_value(op_rows)
    rev_rows = sub[sub['line_item'].str.lower().str.contains('net sal|net sale|revenue|sales', na=False)]
    rev_val = choose_value(rev_rows)
    results.append({'period': y, 'operating_income': op_val, 'revenue': rev_val,
                    'margin_pct': (op_val/rev_val*100) if pd.notna(op_val) and pd.notna(rev_val) and rev_val!=0 else np.nan})

res_df = pd.DataFrame(results)
# compute 3-year average of the per-year unadjusted operating income % margins (ignore years with NaN)
avg_margin = res_df['margin_pct'].mean(skipna=True)
res_df.loc['AVG'] = ['avg', np.nan, np.nan, avg_margin]
# Round margin columns for readability
res_df['margin_pct'] = res_df['margin_pct'].round(4)
# Output per-year margins and the 3-year average (rounded to 1 decimal as requested)
output = {
    'per_year_margins': res_df[['period','operating_income','revenue','margin_pct']],
    'three_year_avg_margin_percent_rounded_1dp': round(float(avg_margin),1) if pd.notna(avg_margin) else None
}
