```python
# Expects the executor to have returned two intermediate tables:
# - The inventory query result (assigned to DF_inv)
# - The cost query result (assigned to DF_cost)
# If those aren't present, it will attempt to use a full DF and re-filter.

import pandas as pd

def to_millions(number, unit):
    if pd.isna(number):
        return None
    u = (unit or '').strip().lower()
    if 'thousand' in u or 'thousands' in u:
        return float(number) / 1000.0
    if 'million' in u or 'millions' in u:
        return float(number)
    if 'billion' in u or 'billions' in u:
        return float(number) * 1000.0
    # fallback: assume number already in millions
    return float(number)

# Try to pick up intermediate tables returned by the executor
try:
    inv_df  # noqa: F821
except NameError:
    try:
        DF_inv  # noqa: F821
        inv_df = DF_inv
    except NameError:
        # try using full DF if available
        try:
            inv_df = DF[(DF['line_item'].str.lower().str.contains('invent')) & (DF['period'].isin(['2022','2021']))].copy()
        except Exception:
            inv_df = pd.DataFrame()

try:
    cost_df  # noqa: F821
except NameError:
    try:
        DF_cost  # noqa: F821
        cost_df = DF_cost
    except NameError:
        try:
            cost_df = DF[(DF['period']=='2022') & (DF['line_item'].str.lower().str.contains('cost'))].copy()
        except Exception:
            cost_df = pd.DataFrame()

# Normalize column names if needed
for df_name, df in [('inv_df', inv_df), ('cost_df', cost_df)]:
    if df is None or df.empty:
        continue
    df.columns = [c.strip() for c in df.columns]

# Extract inventory numbers for 2022 and 2021
inv_2022_row = inv_df[inv_df['period']=='2022']
inv_2021_row = inv_df[inv_df['period']=='2021']

if inv_2022_row.shape[0] >= 1:
    inv_2022_num = float(inv_2022_row.iloc[0]['number'])
    inv_2022_unit = inv_2022_row.iloc[0]['unit']
    inv_2022_m = to_millions(inv_2022_num, inv_2022_unit)
else:
    inv_2022_m = None

if inv_2021_row.shape[0] >= 1:
    inv_2021_num = float(inv_2021_row.iloc[0]['number'])
    inv_2021_unit = inv_2021_row.iloc[0]['unit']
    inv_2021_m = to_millions(inv_2021_num, inv_2021_unit)
else:
    inv_2021_m = None

# Pick a likely COGS row from cost_df (choose the first reasonable numeric row)
cogs_m = None
if cost_df is not None and not cost_df.empty:
    # prefer rows whose line_item contains 'cost of sales' or 'cost of goods' exactly
    prioritized = cost_df[cost_df['line_item'].str.lower().str.contains('cost of sales|cost of goods|cost of products|cost of revenues', na=False)]
    chosen = prioritized if not prioritized.empty else cost_df
    # take first numeric row
    for _, r in chosen.iterrows():
        try:
            c_num = float(r['number'])
            c_unit = r['unit']
            cogs_m = to_millions(c_num, c_unit)
            break
        except Exception:
            continue

# Compute average inventory and turnover if possible
result = {}
result['inv_2021_millions'] = inv_2021_m
result['inv_2022_millions'] = inv_2022_m
result['cogs_2022_millions'] = cogs_m

if inv_2021_m is None or inv_2022_m is None:
    result['error'] = 'Missing inventory for 2021 or 2022; cannot compute turnover.'
else:
    avg_inv = (inv_2021_m + inv_2022_m) / 2.0
    result['avg_inventory_millions'] = avg_inv
    if cogs_m is None or avg_inv == 0:
        result['error'] = 'Missing or zero COGS / average inventory; cannot compute turnover.'
    else:
        turnover = cogs_m / avg_inv
        result['inventory_turnover_times'] = turnover

# Print result dictionary (executor will return this as an intermediate table)
print(result)
