reported_2021 = float(DF[(DF['line_item']=='Reported Sales') & (DF['period']=='2021')]['number'].iloc[0])

# Step 2: collect candidate U.S. and International numbers for 2021 and 2022
us_2021 = DF[(DF['line_item']=='U.S.') & (DF['period']=='2021')]['number'].astype(float).tolist()
us_2022 = DF[(DF['line_item']=='U.S.') & (DF['period']=='2022')]['number'].astype(float).tolist()
int_2021 = DF[(DF['line_item']=='International') & (DF['period']=='2021')]['number'].astype(float).tolist()
int_2022 = DF[(DF['line_item']=='International') & (DF['period']=='2022')]['number'].astype(float).tolist()

# Step 3: find the regional pair that matches reported sales for both years
tol = 1e-6
found = None
for u21 in us_2021:
    for u22 in us_2022:
        for i21 in int_2021:
            for i22 in int_2022:
                if abs((u22 + i22) - reported_2022) < tol and abs((u21 + i21) - reported_2021) < tol:
                    found = (u21, u22, i21, i22)
                    break
            if found:
                break
        if found:
            break
    if found:
        break

# Step 4: if not found, fall back to taking the first matching year entries (but prefer found)
if found:
    us21, us22, int21, int22 = found
else:
    us21 = us_2021[0]; us22 = us_2022[0]; int21 = int_2021[0]; int22 = int_2022[0]

# Step 5: compute percent change 2021->2022
def pct_change(old, new):
    return (new - old) / old * 100 if old != 0 else float('nan')

us_growth_pct = pct_change(us21, us22)
int_growth_pct = pct_change(int21, int22)

# Prepare result table
result = pd.DataFrame([
    {'region':'U.S.','2021':us21,'2022':us22,'growth_pct':round(us_growth_pct,2)},
    {'region':'International','2021':int21,'2022':int22,'growth_pct':round(int_growth_pct,2)}
])

