import re

keywords = ['PBNA','AMESA','Europe','Latin America','North America','Asia','Middle East','Africa','AMER','LAC']
def find_geos(text):
    if not isinstance(text, str):
        return ''
    found = set()
    txt = text.lower()
    for k in keywords:
