Step 3 — if the FY2022 amount is stored in the numeric "number" column (with unit in "unit"), extract it as a numeric amount in dollars (handle "millions"). If the amount is embedded in "value", try to parse it. This Python will take the intermediate rows returned above (stored in variable rows) and produce a single numeric answer (0 if no explicit restructuring amount found):
```
import re
def parse_currency_text(s):
    if s is None: 
        return None
    # remove commas and parentheses, keep digits and decimal
    s2 = re.sub(r'[^\d\.\-]', '', str(s))
    try:
        return float(s2)
    except:
        return None

def get_restructuring_fy2022_amount(rows):
    # rows: list of dicts with keys: page,line_item,period,value,number,unit
    for r in rows:
        # skip rows that only denote the year (e.g., value == '2022' or number == 2022)
        if str(r.get('value','')).strip() in ('2022','FY2022','2022.0') or r.get('number') == 2022:
            # look for adjacent/related row with the amount. In many documents year label row is paired with a preceding/following row containing the amount.
            continue
    # Try to find any row where period contains 2022 and number is an amount (not the year)
    for r in rows:
        per = str(r.get('period',''))
        if '2022' in per:
            num = r.get('number')
            if num is not None and str(num) not in ('2022','2022.0'):
                # assume unit 'millions' means number is in millions
                unit = str(r.get('unit','')).lower()
                amt = float(num)
                if 'million' in unit:
                    return amt * 1_000_000
                else:
                    return amt
            # fallback: try parsing value text as amount
            val = parse_currency_text(r.get('value'))
            if val is not None and val != 2022:
                unit = str(r.get('unit','')).lower()
                if 'million' in unit:
                    return val * 1_000_000
                else:
                    return val
    # If nothing found, return 0
    return 0.0

